SELECT [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit, [Gesamt Normierung].[I Gesamt], [Gesamt Normierung].i, [Gesamt Normierung].Cc, [Gesamt Normierung].[t An], [Gesamt Normierung].[t Ka], [Gesamt Normierung].tm, [Gesamt Normierung].Uo, [Gesamt Normierung].Position, [Gesamt Normierung].Ui, [Gesamt Normierung].Uk, [Gesamt Normierung].Unalt, [Gesamt Normierung].UnVgl3, [Gesamt Normierung].iRef, [Gesamt Normierung].tKorr, [Gesamt Normierung].cKorr, [Gesamt Normierung].Un
FROM (tblGewDaten INNER JOIN tblElektrolyseurbezeichnung ON tblGewDaten.IDElektrolyseurVerteilungUN = tblElektrolyseurbezeichnung.Nr) INNER JOIN (qryDatumVerteilungUn INNER JOIN [Gesamt Normierung] ON (qryDatumVerteilungUn.GewDatum = [Gesamt Normierung].Datum) AND (qryDatumVerteilungUn.Elektrolyseur = [Gesamt Normierung].Elektrolyseur)) ON tblElektrolyseurbezeichnung.Bezeichnung = qryDatumVerteilungUn.Elektrolyseur;
